import java.util.HashSet;
import java.util.Set;
import java.util.function.LongSupplier;

public final class SnowflakeInterview {
    private static final long MAX_DELTA = (1L << 41) - 1;
    private final long epoch;
    private final long nodeId;
    private final LongSupplier clock;
    private long lastMs = -1;
    private int sequence;

    public SnowflakeInterview(long epoch, long nodeId, LongSupplier clock) {
        if (epoch < 0 || nodeId < 0 || nodeId >= 1024 || clock == null) {
            throw new IllegalArgumentException("invalid epoch, nodeId or clock");
        }
        this.epoch = epoch;
        this.nodeId = nodeId;
        this.clock = clock;
    }

    public synchronized long nextId() {
        long now = clock.getAsLong();
        if (now < epoch || now - epoch > MAX_DELTA) {
            throw new IllegalStateException("timestamp out of range");
        }
        if (now < lastMs) {
            throw new IllegalStateException("clock moved backwards");
        }
        int nextSequence = now == lastMs ? sequence + 1 : 0;
        if (nextSequence >= 4096) {
            throw new IllegalStateException("sequence exhausted; retry later");
        }
        lastMs = now;
        sequence = nextSequence;
        return ((now - epoch) << 22) | (nodeId << 12) | sequence;
    }

}

import java.sql.*;
import java.util.*;
import java.util.concurrent.*;
/** Reliable range allocation model; callers must never share a consumed range. */
public final class IdRangeStore {
  record Range(long low, long high) {}
  final String url;
  IdRangeStore(String path) { url="jdbc:h2:file:"+path+";LOCK_TIMEOUT=15000"; }
  Connection connect() throws SQLException { return DriverManager.getConnection(url,"sa",""); }
  void init() throws SQLException {
    try(var c=connect();var s=c.createStatement()) {
      s.execute("CREATE TABLE highwater(name VARCHAR PRIMARY KEY, val BIGINT NOT NULL)");
      s.execute("INSERT INTO highwater VALUES('order',0)");
      s.execute("CREATE TABLE allocations(owner VARCHAR, request VARCHAR, amount BIGINT, lo BIGINT, hi BIGINT, PRIMARY KEY(owner,request))");
    }
  }
  Range allocate(String owner,String request,long size, boolean fail) throws SQLException {
    if(owner==null||owner.isBlank()||request==null||request.isBlank()||size<=0) throw new IllegalArgumentException();
    try(var c=connect()) {
      c.setAutoCommit(false);
      try {
        long old;
        try(var s=c.createStatement();var r=s.executeQuery("SELECT val FROM highwater WHERE name='order' FOR UPDATE")) { r.next();old=r.getLong(1); }
        try(var p=c.prepareStatement("SELECT amount,lo,hi FROM allocations WHERE owner=? AND request=?")) {
          p.setString(1,owner);p.setString(2,request);
          try(var r=p.executeQuery()) { if(r.next()) {
            if(r.getLong(1)!=size) throw new IllegalArgumentException("request payload conflict");
            Range saved=new Range(r.getLong(2),r.getLong(3));c.commit();return saved;
          }}
        }
        long high=Math.addExact(old,size);long low=Math.addExact(old,1);
        try(var p=c.prepareStatement("UPDATE highwater SET val=? WHERE name='order'")) { p.setLong(1,high);p.executeUpdate(); }
        try(var p=c.prepareStatement("INSERT INTO allocations VALUES(?,?,?,?,?)")) {
          p.setString(1,owner);p.setString(2,request);p.setLong(3,size);p.setLong(4,low);p.setLong(5,high);p.executeUpdate();
        }
        if(fail) throw new SQLException("injected precommit failure");
        c.commit();return new Range(low,high);
      } catch(Throwable e) { rollbackPreserving(c, e); throw e; }
    }
  }
  static void check(boolean ok){if(!ok)throw new AssertionError();}
  public static void main(String[] args)throws Exception{
    var db=new IdRangeStore(args[0]);db.init();
    List<Range> ranges=new ArrayList<>();
    try(var pool=Executors.newFixedThreadPool(12)){
      List<Future<Range>> fs=new ArrayList<>();
      for(int i=0;i<100;i++){final int id=i;fs.add(pool.submit(()->db.allocate("boot-"+id,"r",1000,false)));}
      for(var f:fs)ranges.add(f.get());
    }
    ranges.sort(Comparator.comparingLong(Range::low));
    long next=1;for(var r:ranges){check(r.low==next && r.high-r.low==999);next=r.high+1;}
    check(next==100001);
    Range original=db.allocate("retry-boot","stable",17,false);
    try(var pool=Executors.newFixedThreadPool(10)){
      List<Future<Range>> fs=new ArrayList<>();
      for(int i=0;i<30;i++)fs.add(pool.submit(()->db.allocate("retry-boot","stable",17,false)));
      for(var f:fs)check(f.get().equals(original));
    }
    try{db.allocate("retry-boot","stable",18,false);throw new AssertionError();}catch(IllegalArgumentException expected){}
    try{db.allocate("crash","x",9,true);throw new AssertionError();}catch(SQLException expected){}
    var reopened=new IdRangeStore(args[0]);Range after=reopened.allocate("new-boot","r",9,false);
    check(after.low==original.high+1);
    try(var c=db.connect();var s=c.createStatement()){s.execute("UPDATE highwater SET val="+(Long.MAX_VALUE-1));}
    try{db.allocate("overflow","r",2,false);throw new AssertionError();}catch(ArithmeticException expected){}
    check(db.allocate("last","r",1,false).high==Long.MAX_VALUE);
    System.out.println("PASS 100 concurrent disjoint ranges =100000 IDs; 30 idempotent retries; conflict/rollback/reopen/overflow");
  }

    // Keep the primary operation failure; rollback is best-effort diagnostic cleanup.
    static boolean rollbackPreserving(Connection connection, Throwable primary) {
        try {
            connection.rollback();
            return true;
        } catch (Throwable rollbackFailure) {
            if (rollbackFailure != primary) primary.addSuppressed(rollbackFailure);
            return false;
        }
    }
}
